INSERT INTO app_positions (id, name, info, tags, questions, cooldown_secs, approval_note, help_url, help_label, sort_order)
VALUES ('beta', 'Beta Testers', 'Try new Omniplex features before anyone else and help us find what''s broken.

Approved testers get early access and the Beta Tester badge.', ARRAY['Testing', 'Feedback']::text[], '[{"id": "use", "question": "How do you use Omniplex?", "paragraph": "Pick as many as you like.", "placeholder": "", "short": true, "type": "multi", "options": ["I vote", "I own a bot", "I own a server", "I make packs or themes", "I browse"]}, {"id": "devices", "question": "What do you use it on?", "paragraph": "", "placeholder": "", "short": true, "type": "multi", "options": ["Desktop browser", "Phone", "Tablet"]}, {"id": "bug-report", "question": "Describe a bug you''ve found anywhere (not just here) as you''d report it.", "paragraph": "What you did, what you expected, and what happened instead.", "placeholder": "", "short": false, "type": "long", "min_length": 80}, {"id": "hours", "question": "How much time could you spend testing in a typical week?", "paragraph": "", "placeholder": "", "short": true, "type": "choice", "options": ["Under an hour", "1 to 3 hours", "More than 3 hours"]}, {"id": "other", "question": "Anything else?", "paragraph": "", "placeholder": "", "short": true, "type": "short", "optional": true}]'::jsonb, 172800, 'Welcome aboard! Join our Discord server if you haven''t already; that''s where we post new things to test.', '/kb/programs/applications', 'How applying works', 7)
ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

