INSERT INTO app_positions (id, name, info, tags, questions, cooldown_secs, approval_note, help_url, help_label, sort_order)
VALUES ('listing_appeal', 'Listing Appeal', 'Think your bot or server was denied, removed or vote banned by mistake? Tell us what happened and management will take another look.

For a ban on your own account, use the Ban Appeal instead.', ARRAY['Appeals']::text[], '[{"id": "kind", "question": "What are you appealing for?", "paragraph": "", "placeholder": "", "short": true, "type": "choice", "options": ["A bot", "A server"]}, {"id": "id", "question": "Its ID", "paragraph": "", "placeholder": "", "short": true, "type": "short"}, {"id": "what-happened", "question": "What happened?", "paragraph": "", "placeholder": "", "short": true, "type": "choice", "options": ["It was denied", "It was removed", "It was vote banned"]}, {"id": "reason", "question": "What reason were you given?", "paragraph": "", "placeholder": "", "short": true, "type": "short"}, {"id": "why", "question": "Why do you think it should be reconsidered?", "paragraph": "", "placeholder": "", "short": false, "type": "long", "min_length": 80}, {"id": "changes", "question": "Have you changed anything since?", "paragraph": "", "placeholder": "", "short": true, "type": "yesno"}, {"id": "changes-details", "question": "What did you change?", "paragraph": "", "placeholder": "", "short": false, "type": "long", "min_length": 30, "show_if": {"question_id": "changes", "values": ["Yes"]}}]'::jsonb, 604800, '', '/kb/bots/rules', 'Listing rules', 8)
ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO app_positions (id, name, info, tags, questions, cooldown_secs, approval_note, help_url, help_label, sort_order)
